pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // Admissible domain: any uint16, but we need a reentrant reader to observe the stored feeRate
        // during an initialize() that will revert after the store.
        vm.assume(_feeRate > 5000); // Must be out-of-range so the buggy version stores then reverts

        ReentrantObserver observer = new ReentrantObserver(c);
        vm.prank(address(observer));
        bool ok;
        try c.initialize(
            address(0), // _baseToken
            address(0), // _nft
            0,          // _virtualBaseTokenReserves
            0,          // _virtualNftReserves
            0,          // _changeFee
            _feeRate,   // out-of-range feeRate
            bytes32(0), // _merkleRoot
            false,      // _useStolenNftOracle
            false       // _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: after any initialize() call (whether it succeeds or reverts),
        // if the call stored feeRate, it must not exceed 5000. The bug stores an invalid
        // feeRate before reverting, so a reentrant observer can read the out-of-range value.
        uint16 observed = observer.observedFeeRate();
        // The reference contract reverts BEFORE storing, so observedFeeRate remains 0.
        // The buggy contract stores _feeRate (>5000) then reverts, so observedFeeRate == _feeRate.
        assertTrue(observed <= 5000);
    }
}

contract ReentrantObserver {
    C public target;
    uint16 public observedFeeRate;
    constructor(C _target) { target = _target; }
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        // During initialize(), the target calls _safeMint which calls onERC721Received on the recipient.
        // At that point, feeRate has been stored (in the buggy version), so we read it.
        observedFeeRate = target.feeRate();
        return this.onERC721Received.selector;
    }
}

