pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        // Bound feeRate to admissible range (<=5000)
        feeRate = uint16(bound(feeRate, 0, 5000));

        // First initialization
        c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties);

        bool secondCallReverted;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties) {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        // The reference always reverts on second initialize; the mutant allows it to succeed.
        // Therefore the general invariant: a call to initialize after the first one must revert.
        assertTrue(secondCallReverted);
    }
}

