pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event Initialize(address indexed baseToken, address indexed nft, uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useStolenNftOracle, bool payRoyalties);

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Keep admissible: feeRate <= 5000, and for simplicity ensure baseToken != nft to avoid confusion
        vm.assume(feeRate <= 5000);
        vm.assume(baseToken != nft);
        // Expect the Initialize event
        vm.recordLogs();
        c.initialize(baseToken, nft, virtualBaseTokenReserves, virtualNftReserves, changeFee, feeRate, merkleRoot, useStolenNftOracle, payRoyalties);
        Vm.Log[] memory logs = vm.getRecordedLogs();
        bool found = false;
        bool matches = false;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == Initialize.selector) {
                found = true;
                (bool useStolenNftOracleEmitted) = abi.decode(logs[i].data, (bool));
                if (useStolenNftOracleEmitted == c.useStolenNftOracle()) {
                    matches = true;
                }
                break;
            }
        }
        assertTrue(found && matches);
    }
}

