    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool _useStolenNftOracle) public {
        // 1. The domain is all bool values, no restriction needed.
        // 2. No adversarial helper required; the initialize function is called directly.
        // 3. After initialization, the stored state must equal the passed argument.
        c.initialize(
            address(0x1),
            address(0x2),
            100,
            200,
            300,
            400,
            bytes32(0),
            _useStolenNftOracle,
