pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(bool _useStolenNftOracle, bool _payRoyalties) public {
        // 1. (optional) vm.assume(...) / bound(...) to keep params in the ADMISSIBLE domain (keep it WIDE)
        // 2. (optional) deploy an adversarial helper (e.g. `new Reverter()`) and pass its address to c when the
        //    bug is about a failing/​re-entrant external party; vm.deal/vm.prank/vm.warp to set up the scenario;
        //    drive c through `initialize`
        // 3. exactly one assertTrue(<general fact reading c>) the reference holds for all inputs and the bug breaks

        // First initialization
        c.initialize(address(0), address(0), 1, 1, 0, 0, bytes32(0), _useStolenNftOracle, _payRoyalties);

        // Attempt a re-initialization with a different _useStolenNftOracle value
        // This call should revert with AlreadyInitialized
        try c.initialize(address(0), address(0), 1, 1, 0, 0, bytes32(0), !_useStolenNftOracle, _payRoyalties) {
            // If it doesn't revert, the test fails
            assertTrue(false);
        } catch {
            // Expected revert, continue
        }

        // The stored useStolenNftOracle must equal the value set in the first initialize call
        assertTrue(c.useStolenNftOracle() == _useStolenNftOracle);
    }
}

