pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 _virtualBaseTokenReserves) public {
        // Restrict to a wide but admissible range; zero is intentionally included to allow both the reference and buggy
        // contract to satisfy the property in that specific case, while the fuzzer can explore many non-zero values.
        vm.assume(_virtualBaseTokenReserves > 0);

        // Call initialize with the fuzzed virtualBaseTokenReserves and dummy values for the rest.
        // The exact values of other parameters should not affect the property regarding virtualBaseTokenReserves.
        c.initialize(
            address(0x1),
            address(0x2),
            _virtualBaseTokenReserves,
            0,
            0,
            1000,
            bytes32(0),
            false,
            false
        );

        // Assert that the stored value matches the parameter passed.
        // Reference contract stores _virtualBaseTokenReserves, buggy contract stores 0.
        assertTrue(c.virtualBaseTokenReserves() == _virtualBaseTokenReserves);
    }
}

